:host {
  display: block;
  min-height: 100%;
}

* {
  box-sizing: border-box;
}

.app {
  min-height: 100vh;
  display: grid;
  place-items: center;
  background: #020617;
  color: #e5e7eb;
  padding: 24px;
}

.layout {
  width: 100%;
  max-width: 760px;
  display: grid;
  grid-template-columns: minmax(0,1fr) minmax(0,1fr);
  align-items: start;
  gap: 16px;
}

.column {
  min-width: 0;
  background: #020617;
  border-radius: 16px;
  border: 1px solid #1f2937;
  padding: 16px;
  display: grid;
  gap: 12px;
}

.title {
  margin: 0;
  font-size: 18px;
  font-weight: 700;
}

.subtitle {
  margin: 4px 0 0;
  font-size: 13px;
  color: #9ca3af;
}

.product-list,.cart-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 8px;
}

.product-card,.cart-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  padding: 10px;
  border-radius: 12px;
  border: 1px solid #1f2937;
  background: #020617;
}

.product-main,.cart-info {
  min-width: 0;
  display: grid;
  gap: 3px;
}

.product-name,.cart-name {
  font-size: 14px;
  font-weight: 600;
}

.product-price {
  font-size: 13px;
  color: #a3e635;
}

.stock-count {
  font-size: 12px;
  color: #94a3b8;
}

.cart-header {
  display: grid;
  gap: 4px;
}

.cart-meta {
  display: flex;
  align-items: center;
  gap: 4px;
  font-size: 12px;
  color: #9ca3af;
}

.unit-price,.line-total,.subtotal,.discount,.grand-total {
  font-variant-numeric: tabular-nums;
}

.times,.equals {
  opacity: .7;
}

.cart-actions {
  display: flex;
  gap: 6px;
}

button {
  border-radius: 999px;
  border: 1px solid #374151;
  background: #020617;
  color: #e5e7eb;
  padding: 7px 12px;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
}

button:hover:not(:disabled) {
  border-color: #a3e635;
}

button:focus-visible,input:focus-visible {
  outline: 3px solid #bef264;
  outline-offset: 2px;
}

button:disabled {
  opacity: .45;
  cursor: not-allowed;
}

button.ghost {
  background: transparent;
}

button.danger {
  border-color: #f97316;
  color: #f97316;
}

.empty {
  margin: 4px 0;
  font-size: 13px;
  color: #6b7280;
}

.promo-form {
  display: grid;
  gap: 6px;
  padding-top: 4px;
  border-top: 1px solid #1f2937;
}

.promo-form label {
  font-size: 13px;
  font-weight: 700;
}

.promo-controls {
  display: flex;
  gap: 8px;
}

.promo-input {
  min-width: 0;
  flex: 1;
  border: 1px solid #475569;
  border-radius: 10px;
  background: #0f172a;
  color: #f8fafc;
  padding: 8px 10px;
}

.apply-promo {
  border-color: #84cc16;
  color: #d9f99d;
}

.promo-feedback,.checkout-status {
  min-height: 18px;
  margin: 0;
  color: #cbd5e1;
  font-size: 12px;
}

.totals {
  display: grid;
  gap: 7px;
  margin: 0;
  padding: 12px;
  border-radius: 12px;
  background: #0f172a;
}

.totals div {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}

.totals dt,.totals dd {
  margin: 0;
}

.totals dt {
  color: #94a3b8;
  font-size: 13px;
}

.grand-total-row {
  padding-top: 7px;
  border-top: 1px solid #334155;
}

.grand-total-row dt,.grand-total {
  color: #f8fafc !important;
  font-weight: 800;
}

.checkout-button {
  width: 100%;
  border-color: #84cc16;
  background: #365314;
  color: #f7fee7;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
  border: 0;
}

@media (max-width:680px) {
  .app {
    padding: 14px;
  }

  .layout {
    grid-template-columns: 1fr;
  }

  .product-card,.cart-row {
    align-items: flex-start;
  }

  .cart-row {
    flex-direction: column;
  }

  .cart-actions {
    align-self: flex-end;
    flex-wrap: wrap;
  }

  .promo-controls {
    align-items: stretch;
    flex-direction: column;
  }
}
